# mlgmpidl: OCaml bindings of GMP and MPFR generated by camlidl
# (libgmp_caml.a).  The C files come from the opam build directory when the
# switch kept it; otherwise they are regenerated with the host camlidl.

SOURCE=opam:mlgmpidl
DEPENDS="camlidl gmp mpfr"

build() {
  local mods m objs=
  mods=$(make_var . IDLMODULES 2>/dev/null || sed -n 's/^IDLMODULES *= *//p' Makefile)
  [ -n "$mods" ] || die "mlgmpidl: no IDLMODULES in the Makefile"
  for m in $mods; do
    [ -f "${m}_caml.c" ] && continue
    log "regenerating ${m}_caml.c with camlidl"
    [ -f Makefile.config ] || cp Makefile.config.model Makefile.config
    # MPFR_VERSION_MAJOR: written by configure, the model does not have it
    make "${m}_caml.c" CAMLIDL="$HOST_BIN/camlidl" PERL=perl CAML_PREFIX="$OCAML_INC" \
      MPFR_VERSION_MAJOR="$(sed -n 's/^#define MPFR_VERSION_MAJOR *//p' "$SYSROOT/include/mpfr.h")" >&2
  done
  for m in gmp $mods; do
    stub_cc "${m}_caml.c" -I.
    objs="$objs ${m}_caml.o"
  done
  # shellcheck disable=SC2086
  mklib gmp_caml $objs
  install_lib libgmp_caml.a
  install_headers . gmp_caml.h
  link_flags gmp_caml "-lcamlidl -lmpfr -lgmp"
  provides mlgmpidl gmp_caml
}
